import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { ChartContainer, ChartTooltip, ChartTooltipContent, type ChartConfig } from "@/components/ui/chart";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Skeleton } from "@/components/ui/skeleton";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { trpc } from "@/lib/trpc";
import { toPng } from "html-to-image";
import { ArrowDown, ArrowUp, BarChart3, BookmarkCheck, Calculator, CalendarRange, Download, FileDown, FileText, FilterX, ImageDown, Info, LoaderCircle, Microscope, Minus, ShieldCheck } from "lucide-react";
import React from "react";
import { Bar, BarChart, CartesianGrid, Cell, Legend, Pie, PieChart, XAxis, YAxis } from "recharts";

const cohorts = [
  { value: "all", label: "All cohorts" }, { value: "stroke", label: "Stroke" }, { value: "multiple_sclerosis", label: "Multiple Sclerosis" }, { value: "abnormal_movements", label: "Abnormal Movements" }, { value: "guillain_barre", label: "Guillain–Barré" }, { value: "myasthenia_gravis", label: "Myasthenia Gravis" }, { value: "myelopathy", label: "Myelopathy" }, { value: "neuro_ophthalmology", label: "Neuro-ophthalmology" }, { value: "cidp", label: "CIDP" },
] as const;
type StatisticsCohort = typeof cohorts[number]["value"];
type CompletionStatus = "all" | "complete" | "incomplete" | "needs_review";
type EnrollmentStatus = "all" | "screened" | "enrolled" | "completed" | "withdrawn" | "ineligible";
type AggregateDimensionRow = { cohort?: string; status?: string; total: number };
export type AggregateChartDatum = { key: string; label: string; total: number; color: string };
export type AggregateComparisonChartDatum = { key: string; label: string; current: number; comparison: number; difference: number };
export type CohortIndicatorDistribution = { key: string; label: string; total: number; percentage: number };
export type CohortClinicalIndicator = { id: string; cohort: string; title: string; numeratorLabel: string; denominatorLabel: string; numerator: number; denominator: number; percentage: number; distribution: CohortIndicatorDistribution[] };
export type CohortIndicatorDistributionComparison = { key: string; label: string; current: number; comparison: number; currentPercentage: number; comparisonPercentage: number; difference: number };
export type ComparisonReportRow = { cohort: string; indicator: string; currentNumerator: number; currentDenominator: number; currentPercentage: number; comparisonNumerator: number; comparisonDenominator: number; comparisonPercentage: number; percentagePointDifference: number };
export type StatisticsViewPreference = { cohort: StatisticsCohort; completeness: CompletionStatus; enrollment: EnrollmentStatus; startDate: string; endDate: string; comparisonStartDate: string; comparisonEndDate: string };
export type CustomStatisticFamily = "cohort" | "completion" | "enrollment" | "data_quality" | "clinical_indicator";
export type CustomStatisticOption = { key: string; family: CustomStatisticFamily; title: string; numeratorLabel: string; denominatorLabel: string; currentNumerator: number; currentDenominator: number; comparisonNumerator?: number; comparisonDenominator?: number };

export type AggregateStatisticsCore = { totalRecords: number; byCohort: Array<{ cohort: string; total: number }>; byEnrollment: Array<{ status: string; total: number }>; byCompleteness: Array<{ status: string; total: number }>; byDataQuality: Array<{ status: string; total: number }>; investigationCoverage: { radiologyRecorded: number; laboratoryRecorded: number; neurologicalRecorded: number; protocolChecklistComplete: number }; cohortIndicators: CohortClinicalIndicator[] };
export type AggregateStatistics = AggregateStatisticsCore & { comparison?: AggregateStatisticsCore };

const statusLabels: Record<string, string> = { complete: "Complete", incomplete: "Incomplete", needs_review: "Needs review", screened: "Screened", enrolled: "Enrolled", completed: "Completed", withdrawn: "Withdrawn", ineligible: "Ineligible", draft: "Draft", query: "Query" };
const cohortColors = ["#197b8a", "#685f98", "#b96d45", "#69855b", "#805e85", "#48809a", "#9b7048", "#4a8d74"];
const completionColors: Record<string, string> = { complete: "#418c63", incomplete: "#ca8a3d", needs_review: "#477ca6" };
const chartConfig = { total: { label: "Records", color: "#287a73" }, current: { label: "Current period", color: "#287a73" }, comparison: { label: "Comparison period", color: "#8b7bb8" } } satisfies ChartConfig;
const preferenceStorageKey = "munr-statistics-view-v1";
const defaultPreference: StatisticsViewPreference = { cohort: "all", completeness: "all", enrollment: "all", startDate: "", endDate: "", comparisonStartDate: "", comparisonEndDate: "" };

export function getStatisticShare(value: number, total: number) { return total ? Math.round((value / total) * 100) : 0; }
export function statisticLabel(value: string) { return statusLabels[value] ?? value.replaceAll("_", " "); }
export function getStatisticsDateRangeLabel(startDate?: string, endDate?: string) { if (startDate && endDate) return `${startDate} to ${endDate}`; if (startDate) return `From ${startDate}`; if (endDate) return `Up to ${endDate}`; return "All registration dates"; }
export function getStatisticDifferenceLabel(current: number, comparison: number) { const difference = current - comparison; return difference === 0 ? "No change" : `${difference > 0 ? "+" : ""}${difference} vs comparison`; }
export function getPercentagePointDifferenceLabel(current: number, comparison: number) { const difference = current - comparison; return difference === 0 ? "No percentage-point change" : `${difference > 0 ? "+" : ""}${difference} percentage points`; }
export function getComparisonSignal(current: number, comparison: number) { const difference = current - comparison; if (difference > 0) return { label: "Increase", difference, className: "border-emerald-200 bg-emerald-50 text-emerald-800" }; if (difference < 0) return { label: "Decrease", difference, className: "border-rose-200 bg-rose-50 text-rose-800" }; return { label: "No change", difference, className: "border-slate-200 bg-slate-50 text-slate-700" }; }
export function normalizeStatisticsViewPreference(saved: unknown): StatisticsViewPreference { if (!saved || typeof saved !== "object") return defaultPreference; return { ...defaultPreference, ...Object.fromEntries(Object.entries(saved as Record<string, unknown>).filter(([key, value]) => key in defaultPreference && typeof value === "string")) } as StatisticsViewPreference; }
export function readStatisticsViewPreference(): StatisticsViewPreference { if (typeof window === "undefined") return defaultPreference; try { return normalizeStatisticsViewPreference(JSON.parse(window.localStorage.getItem(preferenceStorageKey) ?? "{}")); } catch { return defaultPreference; } }
export function saveStatisticsViewPreference(preference: StatisticsViewPreference) { if (typeof window !== "undefined") window.localStorage.setItem(preferenceStorageKey, JSON.stringify(preference)); }
function getAggregateDimensionKey(row: AggregateDimensionRow) { return row.cohort ?? row.status ?? "not_recorded"; }
export function toAggregateChartData(rows: AggregateDimensionRow[] | undefined, palette: "cohort" | "completion" | "default" = "default"): AggregateChartDatum[] { return (rows ?? []).map((row, index) => { const key = getAggregateDimensionKey(row); return { key, label: statisticLabel(key), total: row.total, color: palette === "cohort" ? cohortColors[index % cohortColors.length] : palette === "completion" ? completionColors[key] ?? "#718096" : "#287a73" }; }); }
export function toAggregateComparisonChartData(currentRows: AggregateDimensionRow[] | undefined, comparisonRows: AggregateDimensionRow[] | undefined): AggregateComparisonChartDatum[] { const current = new Map((currentRows ?? []).map(row => [getAggregateDimensionKey(row), row.total])); const comparison = new Map((comparisonRows ?? []).map(row => [getAggregateDimensionKey(row), row.total])); const keys = [...Array.from(current.keys()), ...Array.from(comparison.keys()).filter(key => !current.has(key))]; return keys.map(key => ({ key, label: statisticLabel(key), current: current.get(key) ?? 0, comparison: comparison.get(key) ?? 0, difference: (current.get(key) ?? 0) - (comparison.get(key) ?? 0) })); }
export function toCohortIndicatorDistributionComparison(current?: CohortClinicalIndicator, comparison?: CohortClinicalIndicator): CohortIndicatorDistributionComparison[] { const currentByKey = new Map((current?.distribution ?? []).map(row => [row.key, row])); const comparisonByKey = new Map((comparison?.distribution ?? []).map(row => [row.key, row])); const keys = [...Array.from(currentByKey.keys()), ...Array.from(comparisonByKey.keys()).filter(key => !currentByKey.has(key))]; return keys.map(key => { const a = currentByKey.get(key); const b = comparisonByKey.get(key); return { key, label: a?.label ?? b?.label ?? statisticLabel(key), current: a?.total ?? 0, comparison: b?.total ?? 0, currentPercentage: a?.percentage ?? 0, comparisonPercentage: b?.percentage ?? 0, difference: (a?.percentage ?? 0) - (b?.percentage ?? 0) }; }); }
export function toComparisonReportRows(currentIndicators: CohortClinicalIndicator[], comparisonIndicators: CohortClinicalIndicator[]): ComparisonReportRow[] { const comparisonById = new Map(comparisonIndicators.map(indicator => [indicator.id, indicator])); return currentIndicators.map(indicator => { const comparison = comparisonById.get(indicator.id); const comparisonPercentage = comparison?.percentage ?? 0; return { cohort: cohorts.find(item => item.value === indicator.cohort)?.label ?? statisticLabel(indicator.cohort), indicator: indicator.title, currentNumerator: indicator.numerator, currentDenominator: indicator.denominator, currentPercentage: indicator.percentage, comparisonNumerator: comparison?.numerator ?? 0, comparisonDenominator: comparison?.denominator ?? 0, comparisonPercentage, percentagePointDifference: indicator.percentage - comparisonPercentage }; }).filter(row => row.currentDenominator > 0 || row.comparisonDenominator > 0); }
export function buildComparisonSummary(data: AggregateStatisticsCore, comparison: AggregateStatisticsCore, currentLabel: string, comparisonLabel: string) { const recordDifference = data.totalRecords - comparison.totalRecords; const indicators = toComparisonReportRows(data.cohortIndicators, comparison.cohortIndicators).sort((a, b) => Math.abs(b.percentagePointDifference) - Math.abs(a.percentagePointDifference)); const headline = `Observed aggregate comparison: ${data.totalRecords} matching records in ${currentLabel} versus ${comparison.totalRecords} in ${comparisonLabel} (${recordDifference > 0 ? "+" : ""}${recordDifference}).`; const indicatorLine = indicators[0] ? `${indicators[0].cohort}: ${indicators[0].indicator} changed by ${indicators[0].percentagePointDifference > 0 ? "+" : ""}${indicators[0].percentagePointDifference} percentage points (${indicators[0].currentPercentage}% versus ${indicators[0].comparisonPercentage}%).` : "No cohort indicator has a matching denominator in either selected period."; return [headline, indicatorLine, "This describes observed aggregate differences only; it does not establish a clinical, operational, or causal explanation.", "For approved research review, consider cohort mix, enrollment activity, documentation completeness, and service availability before interpreting a difference."]; }
export function getCustomStatisticOptions(data: AggregateStatisticsCore, comparison?: AggregateStatisticsCore): CustomStatisticOption[] {
  const withDimension = (family: Exclude<CustomStatisticFamily, "clinical_indicator">, label: string, currentRows: AggregateDimensionRow[], comparisonRows: AggregateDimensionRow[] | undefined) => currentRows.map(row => { const key = getAggregateDimensionKey(row); const comparisonRow = comparisonRows?.find(item => getAggregateDimensionKey(item) === key); return { key: `${family}:${key}`, family, title: `${statisticLabel(key)} ${label}`, numeratorLabel: statisticLabel(key), denominatorLabel: "All matching records", currentNumerator: row.total, currentDenominator: data.totalRecords, comparisonNumerator: comparisonRow?.total, comparisonDenominator: comparison?.totalRecords }; });
  const cohortOptions = withDimension("cohort", "cohort share", data.byCohort, comparison?.byCohort);
  const completionOptions = withDimension("completion", "completion status share", data.byCompleteness, comparison?.byCompleteness);
  const enrollmentOptions = withDimension("enrollment", "enrollment status share", data.byEnrollment, comparison?.byEnrollment);
  const qualityOptions = withDimension("data_quality", "data-quality status share", data.byDataQuality, comparison?.byDataQuality);
  const comparisonById = new Map((comparison?.cohortIndicators ?? []).map(item => [item.id, item]));
  const clinicalOptions = data.cohortIndicators.map(indicator => { const prior = comparisonById.get(indicator.id); return { key: `clinical_indicator:${indicator.id}`, family: "clinical_indicator" as const, title: indicator.title, numeratorLabel: indicator.numeratorLabel, denominatorLabel: indicator.denominatorLabel, currentNumerator: indicator.numerator, currentDenominator: indicator.denominator, comparisonNumerator: prior?.numerator, comparisonDenominator: prior?.denominator }; });
  return [...cohortOptions, ...completionOptions, ...enrollmentOptions, ...qualityOptions, ...clinicalOptions];
}
export function buildCustomStatisticSummary(option: CustomStatisticOption, currentLabel: string, comparisonLabel?: string) { const currentPercentage = getStatisticShare(option.currentNumerator, option.currentDenominator); const base = `${option.numeratorLabel}: ${option.currentNumerator} of ${option.currentDenominator} ${option.denominatorLabel.toLowerCase()} (${currentPercentage}%) in ${currentLabel}.`; if (option.comparisonNumerator === undefined || option.comparisonDenominator === undefined || !comparisonLabel) return [base, "This is an observed aggregate proportion, not a causal explanation."]; const comparisonPercentage = getStatisticShare(option.comparisonNumerator, option.comparisonDenominator); return [base, `Comparison period: ${option.comparisonNumerator} of ${option.comparisonDenominator} (${comparisonPercentage}%); change: ${getPercentagePointDifferenceLabel(currentPercentage, comparisonPercentage)}.`, "This is an observed aggregate proportion, not a clinical, operational, or causal explanation."]; }
export function createCustomStatisticCsv(option: CustomStatisticOption, currentLabel: string, comparisonLabel?: string) { const currentPercentage = getStatisticShare(option.currentNumerator, option.currentDenominator); const rows = [["Statistic", option.title], ["Numerator", option.numeratorLabel], ["Denominator", option.denominatorLabel], ["Current registration date range (UTC)", currentLabel], ["Current numerator", String(option.currentNumerator)], ["Current denominator", String(option.currentDenominator)], ["Current share", `${currentPercentage}%`]]; if (option.comparisonNumerator !== undefined && option.comparisonDenominator !== undefined && comparisonLabel) { const comparisonPercentage = getStatisticShare(option.comparisonNumerator, option.comparisonDenominator); rows.push(["Comparison registration date range (UTC)", comparisonLabel], ["Comparison numerator", String(option.comparisonNumerator)], ["Comparison denominator", String(option.comparisonDenominator)], ["Comparison share", `${comparisonPercentage}%`], ["Percentage-point difference", String(currentPercentage - comparisonPercentage)]); } return ["Field,Value", ...rows.map(row => row.map(value => `\"${value.replaceAll('\"', '\"\"')}\"`).join(","))].join("\r\n"); }
function appendRows(rows: Array<Array<string | number>>, dimension: string, current: AggregateDimensionRow[], comparison?: AggregateDimensionRow[]) { if (comparison) toAggregateComparisonChartData(current, comparison).forEach(row => rows.push([dimension, row.label, row.current, row.comparison, row.difference])); else current.forEach(row => rows.push([dimension, statisticLabel(getAggregateDimensionKey(row)), row.total, `${getStatisticShare(row.total, current.reduce((sum, item) => sum + item.total, 0))}%`])); }
export function createAggregateStatisticsCsv(data: AggregateStatisticsCore, currentDateRangeLabel = "All registration dates", comparison?: AggregateStatisticsCore, comparisonDateRangeLabel?: string) { const comparisonRows = comparison ? toComparisonReportRows(data.cohortIndicators, comparison.cohortIndicators) : []; const rows: Array<Array<string | number>> = comparison ? [["Records", "All matching records", data.totalRecords, comparison.totalRecords, data.totalRecords - comparison.totalRecords]] : [["Records", "All matching records", data.totalRecords, "100%"]]; appendRows(rows, "Cohort", data.byCohort, comparison?.byCohort); appendRows(rows, "Completion status", data.byCompleteness, comparison?.byCompleteness); appendRows(rows, "Enrollment status", data.byEnrollment, comparison?.byEnrollment); appendRows(rows, "Data quality", data.byDataQuality, comparison?.byDataQuality); const coverage: Array<[string, number, number?]> = [["Radiology recorded", data.investigationCoverage.radiologyRecorded, comparison?.investigationCoverage.radiologyRecorded], ["Laboratory recorded", data.investigationCoverage.laboratoryRecorded, comparison?.investigationCoverage.laboratoryRecorded], ["Neurological recorded", data.investigationCoverage.neurologicalRecorded, comparison?.investigationCoverage.neurologicalRecorded], ["Protocol checklist complete", data.investigationCoverage.protocolChecklistComplete, comparison?.investigationCoverage.protocolChecklistComplete]]; coverage.forEach(([label, current, prior]) => rows.push(comparison ? ["Investigation coverage", label, current, prior ?? 0, current - (prior ?? 0)] : ["Investigation coverage", label, current, `${getStatisticShare(current, data.totalRecords)}%`])); if (comparison) comparisonRows.forEach(row => { rows.push(["Cohort indicator", `${row.indicator} — numerator`, row.currentNumerator, row.comparisonNumerator, row.currentNumerator - row.comparisonNumerator]); rows.push(["Cohort indicator", `${row.indicator} — denominator`, row.currentDenominator, row.comparisonDenominator, row.currentDenominator - row.comparisonDenominator]); }); else data.cohortIndicators.filter(indicator => indicator.denominator > 0).forEach(indicator => { rows.push(["Cohort indicator", `${indicator.title} — numerator`, indicator.numerator, `${indicator.percentage}%`]); rows.push(["Cohort indicator", `${indicator.title} — denominator`, indicator.denominator, "100%"]); }); const header = comparison ? "Dimension,Category,Current count,Comparison count,Difference" : "Dimension,Category,Count,Share"; const preface = comparison ? [`# Current registration date range (UTC): ${currentDateRangeLabel}`, `# Comparison registration date range (UTC): ${comparisonDateRangeLabel ?? "Not selected"}`] : [`# Registration date range (UTC): ${currentDateRangeLabel}`]; return [...preface, header, ...rows.map(row => row.map(value => `"${String(value).replaceAll('"', '""')}"`).join(","))].join("\r\n"); }
function reportDate() { return new Date().toISOString().slice(0, 10); }
function downloadBlob(blob: Blob, fileName: string) { const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = fileName; document.body.appendChild(link); link.click(); link.remove(); window.setTimeout(() => URL.revokeObjectURL(url), 0); }
export function downloadAggregateStatisticsCsv(csv: string) { downloadBlob(new Blob(["\uFEFF", csv], { type: "text/csv;charset=utf-8" }), csv.includes("# Comparison registration date range (UTC):") ? `registry-comparison-report-${reportDate()}.csv` : `registry-aggregate-statistics-${reportDate()}.csv`); }
export function getStatisticsChartPngFileName(title: string, date = new Date()) { const stem = title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "aggregate-chart"; return `registry-statistics-${stem}-${date.toISOString().slice(0, 10)}.png`; }
export async function downloadStatisticsChartPng(target: HTMLElement, title: string) { const dataUrl = await toPng(target, { backgroundColor: "#ffffff", cacheBust: true, pixelRatio: 2 }); const link = document.createElement("a"); link.href = dataUrl; link.download = getStatisticsChartPngFileName(title); document.body.appendChild(link); link.click(); link.remove(); }
export async function downloadComparisonReportPdf(data: AggregateStatisticsCore, comparison: AggregateStatisticsCore, currentLabel: string, comparisonLabel: string) { const { jsPDF } = await import("jspdf"); const pdf = new jsPDF({ unit: "pt", format: "a4" }); const lines = ["Mansoura University Neurology Research Registry", "Aggregate Statistics Comparison Report", `Current period (UTC): ${currentLabel}`, `Comparison period (UTC): ${comparisonLabel}`, "", ...buildComparisonSummary(data, comparison, currentLabel, comparisonLabel), "", "Cohort indicators (current vs comparison):", ...toComparisonReportRows(data.cohortIndicators, comparison.cohortIndicators).map(row => `${row.cohort} — ${row.indicator}: ${row.currentPercentage}% vs ${row.comparisonPercentage}% (${row.percentagePointDifference > 0 ? "+" : ""}${row.percentagePointDifference} pp)`), "", "Contains aggregate research statistics only. No individual records or identifiers are included."]; let y = 48; lines.forEach(line => { const wrapped = pdf.splitTextToSize(line, 510) as string[]; if (y + wrapped.length * 15 > 790) { pdf.addPage(); y = 48; } pdf.text(wrapped, 42, y); y += wrapped.length * 15 + 5; }); pdf.save(`registry-comparison-report-${reportDate()}.pdf`); }
export async function downloadComparisonReportWord(data: AggregateStatisticsCore, comparison: AggregateStatisticsCore, currentLabel: string, comparisonLabel: string) { const { Document, HeadingLevel, Packer, Paragraph } = await import("docx"); const lines = ["Mansoura University Neurology Research Registry", "Aggregate Statistics Comparison Report", `Current period (UTC): ${currentLabel}`, `Comparison period (UTC): ${comparisonLabel}`, "", ...buildComparisonSummary(data, comparison, currentLabel, comparisonLabel), "", "Cohort indicators (current vs comparison):", ...toComparisonReportRows(data.cohortIndicators, comparison.cohortIndicators).map(row => `${row.cohort} — ${row.indicator}: ${row.currentPercentage}% vs ${row.comparisonPercentage}% (${row.percentagePointDifference > 0 ? "+" : ""}${row.percentagePointDifference} percentage points)`), "", "Contains aggregate research statistics only. No individual records or identifiers are included."]; const documentFile = new Document({ sections: [{ children: lines.map((line, index) => new Paragraph({ text: line, heading: index === 0 ? HeadingLevel.HEADING_1 : index === 1 ? HeadingLevel.HEADING_2 : undefined })) }] }); downloadBlob(await Packer.toBlob(documentFile), `registry-comparison-report-${reportDate()}.docx`); }

async function downloadCustomStatisticDocument(option: CustomStatisticOption, currentLabel: string, comparisonLabel: string | undefined, format: "pdf" | "word") { const lines = ["Mansoura University Neurology Research Registry", "Custom aggregate research statistic", "", ...buildCustomStatisticSummary(option, currentLabel, comparisonLabel), "", "Contains aggregate research statistics only. No individual records or identifiers are included."]; if (format === "pdf") { const { jsPDF } = await import("jspdf"); const pdf = new jsPDF({ unit: "pt", format: "a4" }); let y = 48; lines.forEach(line => { const wrapped = pdf.splitTextToSize(line, 510) as string[]; if (y + wrapped.length * 15 > 790) { pdf.addPage(); y = 48; } pdf.text(wrapped, 42, y); y += wrapped.length * 15 + 5; }); pdf.save(`registry-custom-statistic-${reportDate()}.pdf`); return; } const { Document, HeadingLevel, Packer, Paragraph } = await import("docx"); const documentFile = new Document({ sections: [{ children: lines.map((line, index) => new Paragraph({ text: line, heading: index === 0 ? HeadingLevel.HEADING_1 : index === 1 ? HeadingLevel.HEADING_2 : undefined })) }] }); downloadBlob(await Packer.toBlob(documentFile), `registry-custom-statistic-${reportDate()}.docx`); }
function ChartHelp({ label, children }: { label: string; children: React.ReactNode }) { return <Tooltip><TooltipTrigger asChild><button type="button" aria-label={`Help for ${label}`} className="inline-flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-[#51767a] outline-none transition-colors hover:bg-[#e6f4f0] hover:text-[#1f6965] focus-visible:ring-2 focus-visible:ring-[#2d7a73]"><Info className="h-4 w-4" aria-hidden="true" /></button></TooltipTrigger><TooltipContent side="top" sideOffset={6} className="max-w-64 bg-[#1d3c46] text-white">{children}</TooltipContent></Tooltip>; }
function ComparisonSignal({ current, comparison, percentagePoints = false }: { current: number; comparison: number; percentagePoints?: boolean }) { const signal = getComparisonSignal(current, comparison); const Icon = signal.difference > 0 ? ArrowUp : signal.difference < 0 ? ArrowDown : Minus; const text = percentagePoints ? getPercentagePointDifferenceLabel(current, comparison) : getStatisticDifferenceLabel(current, comparison); return <span className={`inline-flex items-center gap-1 rounded-full border px-2 py-1 text-[11px] font-semibold ${signal.className}`}><Icon className="h-3.5 w-3.5" aria-hidden="true" />{signal.label}: {text}</span>; }
function ChartPngExport({ chartId, title }: { chartId: string; title: string }) { const [loading, setLoading] = React.useState(false); const [error, setError] = React.useState(""); const exportPng = async () => { const chart = document.getElementById(chartId); if (!chart) { setError("The chart could not be prepared. Please try again."); return; } setLoading(true); setError(""); try { await downloadStatisticsChartPng(chart, title); } catch { setError("The chart could not be prepared. Please try again."); } finally { setLoading(false); } }; return <div className="mt-4 flex flex-wrap items-center gap-3"><Button type="button" size="sm" variant="outline" className="border-[#b8dcd5] text-[#22636a]" disabled={loading} onClick={exportPng}>{loading ? <LoaderCircle className="mr-2 h-3.5 w-3.5 animate-spin" /> : <ImageDown className="mr-2 h-3.5 w-3.5" />}{loading ? "Preparing PNG…" : "Export PNG"}</Button>{error ? <p role="status" className="text-xs text-rose-700">{error}</p> : <p className="text-xs text-slate-500">Exports this aggregate chart only.</p>}</div>; }
function AggregateDonutChart({ title, description, data, total, selectedKey, onSelect, dateRangeLabel }: { title: string; description: string; data: AggregateChartDatum[]; total: number; selectedKey: string; onSelect: (key: string) => void; dateRangeLabel: string }) { const id = React.useId(); return <Card className="border-[#e1e9e5] shadow-sm"><CardHeader className="pb-1"><div className="flex items-start justify-between gap-2"><CardTitle className="text-base text-[#24434b]">{title}</CardTitle><ChartHelp label={title}>Hover a segment for its aggregate count and share. Select a category below to filter the aggregate view.</ChartHelp></div><CardDescription>{description}</CardDescription></CardHeader><CardContent><div id={id} className="rounded-xl bg-[#fbfefd] p-2"><p className="px-2 pt-1 text-sm font-semibold text-[#24434b]">{title}</p><p className="px-2 pt-1 text-[11px] text-[#587579]">Registration date (UTC): {dateRangeLabel}</p><ChartContainer config={chartConfig} className="mx-auto h-[230px] max-w-[310px]"><PieChart><ChartTooltip content={<ChartTooltipContent hideLabel formatter={value => `${value} records (${getStatisticShare(Number(value), total)}%)`} />} /><Pie data={data} dataKey="total" nameKey="label" innerRadius={59} outerRadius={92} paddingAngle={3} strokeWidth={0}>{data.map(item => <Cell key={item.key} fill={item.color} />)}</Pie><text x="50%" y="47%" textAnchor="middle" className="fill-[#1d3c46] text-2xl font-semibold">{total}</text><text x="50%" y="58%" textAnchor="middle" className="fill-[#68807e] text-[10px] font-medium">MATCHING RECORDS</text></PieChart></ChartContainer><div className="grid gap-1.5 px-2 pb-2 text-xs text-[#45616a]">{data.map(item => <div key={item.key} className="flex items-center justify-between gap-2"><span className="flex items-center gap-2"><span className="h-2.5 w-2.5 rounded-full" style={{ backgroundColor: item.color }} />{item.label}</span><span className="font-medium tabular-nums">{item.total} · {getStatisticShare(item.total, total)}%</span></div>)}</div></div><div className="mt-4 grid gap-2 sm:grid-cols-2" aria-label={`${title} filters`}>{data.map(item => <button key={item.key} type="button" onClick={() => onSelect(item.key)} aria-pressed={selectedKey === item.key} className={`flex min-h-10 items-center justify-between gap-2 rounded-lg border px-2.5 text-left text-xs focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#2d7a73] ${selectedKey === item.key ? "border-[#5fa397] bg-[#edf8f5] text-[#184a47]" : "border-[#e0ebe7] bg-white text-[#45616a] hover:bg-[#f4faf8]"}`}><span className="truncate">{item.label}</span><span className="font-semibold tabular-nums">{item.total} · {getStatisticShare(item.total, total)}%</span></button>)}</div><ChartPngExport chartId={id} title={title} /></CardContent></Card>; }
function AggregateBarChart({ title, data, total, dateRangeLabel }: { title: string; data: AggregateChartDatum[]; total: number; dateRangeLabel: string }) { const id = React.useId(); return <Card className="border-[#e1e9e5] shadow-sm"><CardHeader className="pb-2"><div className="flex items-start justify-between gap-2"><CardTitle className="text-base text-[#24434b]">{title}</CardTitle><ChartHelp label={title}>Hover a bar to see its aggregate count and share of matching records.</ChartHelp></div><CardDescription>Counts and shares for the active aggregate view.</CardDescription></CardHeader><CardContent><div id={id} className="rounded-xl bg-[#fbfefd] p-2"><p className="px-2 pt-1 text-sm font-semibold text-[#24434b]">{title}</p><p className="px-2 pt-1 text-[11px] text-[#587579]">Registration date (UTC): {dateRangeLabel}</p><ChartContainer config={chartConfig} className="h-[230px] w-full"><BarChart accessibilityLayer data={data} margin={{ left: -14, right: 8, top: 8 }}><CartesianGrid vertical={false} stroke="#e7efec" /><XAxis dataKey="label" tickLine={false} axisLine={false} tickMargin={8} interval={0} angle={-18} textAnchor="end" height={64} /><YAxis allowDecimals={false} tickLine={false} axisLine={false} width={28} /><ChartTooltip cursor={{ fill: "#edf7f4" }} content={<ChartTooltipContent formatter={value => `${value} (${getStatisticShare(Number(value), total)}%)`} />} /><Bar dataKey="total" fill="var(--color-total)" radius={[5, 5, 0, 0]} /></BarChart></ChartContainer></div><ChartPngExport chartId={id} title={title} /></CardContent></Card>; }
function AggregateComparisonBarChart({ title, currentRows, comparisonRows, currentDateRangeLabel, comparisonDateRangeLabel }: { title: string; currentRows: AggregateDimensionRow[]; comparisonRows: AggregateDimensionRow[]; currentDateRangeLabel: string; comparisonDateRangeLabel: string }) { const id = React.useId(); const data = toAggregateComparisonChartData(currentRows, comparisonRows); return <Card className="border-[#d7e4df] shadow-sm"><CardHeader className="pb-2"><div className="flex items-start justify-between gap-2"><CardTitle className="text-base text-[#24434b]">{title}</CardTitle><ChartHelp label={title}>Hover bar pairs for aggregate counts. The badges say Increase, Decrease, or No change as well as using colour.</ChartHelp></div><CardDescription>Current period versus comparison period.</CardDescription></CardHeader><CardContent><div id={id} className="rounded-xl bg-[#fbfefd] p-2"><p className="px-2 pt-1 text-sm font-semibold text-[#24434b]">{title}</p><p className="px-2 pt-1 text-[11px] text-[#587579]">Current: {currentDateRangeLabel} · Comparison: {comparisonDateRangeLabel}</p><ChartContainer config={chartConfig} className="h-[270px] w-full"><BarChart accessibilityLayer data={data} margin={{ left: -14, right: 8, top: 14 }}><CartesianGrid vertical={false} stroke="#e7efec" /><XAxis dataKey="label" tickLine={false} axisLine={false} tickMargin={8} interval={0} angle={-18} textAnchor="end" height={72} /><YAxis allowDecimals={false} tickLine={false} axisLine={false} width={28} /><ChartTooltip cursor={{ fill: "#edf7f4" }} content={<ChartTooltipContent formatter={(value, name) => `${value} ${name === "comparison" ? "in comparison period" : "in current period"}`} />} /><Legend formatter={value => value === "current" ? "Current period" : "Comparison period"} /><Bar name="current" dataKey="current" fill="var(--color-current)" radius={[4, 4, 0, 0]} /><Bar name="comparison" dataKey="comparison" fill="var(--color-comparison)" radius={[4, 4, 0, 0]} /></BarChart></ChartContainer><div className="grid gap-2 px-2 pb-2 text-xs text-[#45616a]">{data.map(item => <div key={item.key} className="flex flex-wrap items-center justify-between gap-2"><span>{item.label}</span><span className="flex flex-wrap items-center justify-end gap-1.5 font-medium tabular-nums"><span>{item.current} vs {item.comparison}</span><ComparisonSignal current={item.current} comparison={item.comparison} /></span></div>)}</div></div><ChartPngExport chartId={id} title={`${title} comparison`} /></CardContent></Card>; }
function CohortIndicatorCard({ indicator, comparison, currentDateRangeLabel, comparisonDateRangeLabel }: { indicator: CohortClinicalIndicator; comparison?: CohortClinicalIndicator; currentDateRangeLabel: string; comparisonDateRangeLabel?: string }) { const id = React.useId(); const isComparison = Boolean(comparison); const distribution = toCohortIndicatorDistributionComparison(indicator, comparison); const rates = [{ label: "Rate", current: indicator.percentage, comparison: comparison?.percentage ?? 0 }]; return <Card className="border-[#d7e4df] shadow-sm"><CardHeader className="pb-2"><CardDescription>{cohorts.find(item => item.value === indicator.cohort)?.label ?? statisticLabel(indicator.cohort)}</CardDescription><div className="flex items-start justify-between gap-2"><CardTitle className="text-base text-[#24434b]">{indicator.title}</CardTitle><ChartHelp label={indicator.title}>This card reports a controlled cohort-field numerator over all matching records in the cohort. Hover the rate chart for the aggregate values.</ChartHelp></div></CardHeader><CardContent><div id={id} className="rounded-xl bg-[#fbfefd] p-3"><p className="text-sm font-semibold text-[#24434b]">{indicator.numeratorLabel}</p><p className="mt-1 text-xs text-[#587579]">{indicator.denominatorLabel}</p><div className="mt-3 flex items-baseline gap-3"><span className="text-3xl font-semibold tracking-tight text-[#1d3c46]">{indicator.percentage}%</span><span className="text-xs text-[#587579]">{indicator.numerator} of {indicator.denominator}</span></div>{isComparison ? <div className="mt-2"><ComparisonSignal current={indicator.percentage} comparison={comparison?.percentage ?? 0} percentagePoints /></div> : null}<p className="mt-3 text-[11px] text-[#587579]">Current: {currentDateRangeLabel}{isComparison ? ` · Comparison: ${comparisonDateRangeLabel}` : ""}</p><ChartContainer config={chartConfig} className="mt-2 h-[160px] w-full"><BarChart accessibilityLayer data={rates} margin={{ left: -18, right: 8, top: 8 }}><CartesianGrid vertical={false} stroke="#e7efec" /><XAxis dataKey="label" hide /><YAxis domain={[0, 100]} tickFormatter={value => `${value}%`} tickLine={false} axisLine={false} width={40} /><ChartTooltip cursor={{ fill: "#edf7f4" }} content={<ChartTooltipContent formatter={(value, name) => `${value}% ${name === "comparison" ? "in comparison period" : "in current period"}`} />} />{isComparison ? <Legend formatter={value => value === "current" ? "Current period" : "Comparison period"} /> : null}<Bar name="current" dataKey="current" fill="var(--color-current)" radius={[5, 5, 0, 0]} />{isComparison ? <Bar name="comparison" dataKey="comparison" fill="var(--color-comparison)" radius={[5, 5, 0, 0]} /> : null}</BarChart></ChartContainer><div className="mt-2 border-t border-[#dfeae6] pt-2 text-xs text-[#45616a]">{distribution.map(row => <div key={row.key} className="flex flex-wrap items-center justify-between gap-2 py-0.5"><span>{row.label}</span><span className="font-medium tabular-nums">{isComparison ? `${row.currentPercentage}% vs ${row.comparisonPercentage}%` : `${row.currentPercentage}%`} · {isComparison ? getPercentagePointDifferenceLabel(row.currentPercentage, row.comparisonPercentage) : `${row.current} records`}</span></div>)}</div></div><ChartPngExport chartId={id} title={`${indicator.title} ${isComparison ? "comparison" : "rate"}`} /></CardContent></Card>; }
function Metric({ label, value, description, comparisonValue }: { label: string; value: number; description: string; comparisonValue?: number }) { return <Card className="border-[#e1e9e5] shadow-sm"><CardContent className="p-5"><p className="text-xs font-medium text-slate-500">{label}</p><p className="mt-2 text-2xl font-semibold tracking-tight text-[#1d333f]">{value}</p><p className="mt-2 text-xs leading-5 text-slate-500">{description}</p>{comparisonValue !== undefined ? <div className="mt-3"><ComparisonSignal current={value} comparison={comparisonValue} /></div> : null}</CardContent></Card>; }
function ComparisonSummary({ data, comparison, currentLabel, comparisonLabel }: { data: AggregateStatisticsCore; comparison: AggregateStatisticsCore; currentLabel: string; comparisonLabel: string }) { return <Card className="border-[#b8dcd5] bg-[#f6fbf9]"><CardHeader className="pb-2"><CardTitle className="text-lg text-[#24434b]">Descriptive comparison summary</CardTitle><CardDescription>Observed aggregate changes only. This text does not state the cause of a difference.</CardDescription></CardHeader><CardContent><div className="space-y-2 text-sm leading-6 text-[#45616a]">{buildComparisonSummary(data, comparison, currentLabel, comparisonLabel).map((line, index) => <p key={line} className={index < 2 ? "font-medium text-[#24434b]" : ""}>{line}</p>)}</div></CardContent></Card>; }
function ReportActions({ data, comparison, preference, currentLabel, comparisonLabel }: { data?: AggregateStatisticsCore; comparison?: AggregateStatisticsCore; preference: StatisticsViewPreference; currentLabel: string; comparisonLabel: string }) { const [saved, setSaved] = React.useState(false); const [exporting, setExporting] = React.useState<"pdf" | "word" | null>(null); const [error, setError] = React.useState(""); const hasComparison = Boolean(data && comparison); const saveView = () => { saveStatisticsViewPreference(preference); setSaved(true); window.setTimeout(() => setSaved(false), 1800); }; const exportReport = async (format: "pdf" | "word") => { if (!data || !comparison) return; setError(""); setExporting(format); try { if (format === "pdf") await downloadComparisonReportPdf(data, comparison, currentLabel, comparisonLabel); else await downloadComparisonReportWord(data, comparison, currentLabel, comparisonLabel); } catch { setError("The comparison report could not be prepared. Please try again."); } finally { setExporting(null); } }; return <div className="flex flex-wrap items-center gap-2"><Button type="button" variant="outline" className="border-[#b8dcd5] text-[#22636a]" onClick={saveView}><BookmarkCheck className="mr-2 h-4 w-4" />{saved ? "View saved locally" : "Save view"}</Button><Button type="button" variant="outline" disabled={!hasComparison || exporting !== null} onClick={() => exportReport("pdf")}><FileDown className="mr-2 h-4 w-4" />{exporting === "pdf" ? "Preparing PDF…" : "Export PDF"}</Button><Button type="button" variant="outline" disabled={!hasComparison || exporting !== null} onClick={() => exportReport("word")}><FileText className="mr-2 h-4 w-4" />{exporting === "word" ? "Preparing Word…" : "Export Word"}</Button>{!hasComparison ? <span className="text-xs text-slate-500">Choose both comparison dates to export a comparison report.</span> : null}{error ? <span role="status" className="text-xs text-rose-700">{error}</span> : null}</div>; }

function CustomStatisticBuilder({ data, comparison, currentLabel, comparisonLabel }: { data: AggregateStatisticsCore; comparison?: AggregateStatisticsCore; currentLabel: string; comparisonLabel: string }) { const targetId = React.useId(); const options = React.useMemo(() => getCustomStatisticOptions(data, comparison), [data, comparison]); const [family, setFamily] = React.useState<CustomStatisticFamily>("cohort"); const [selectedKey, setSelectedKey] = React.useState(""); const familyOptions = options.filter(option => option.family === family); const selected = familyOptions.find(option => option.key === selectedKey) ?? familyOptions[0] ?? options[0]; const [exporting, setExporting] = React.useState<"png" | "pdf" | "word" | null>(null); const [error, setError] = React.useState(""); if (!selected) return null; const currentPercentage = getStatisticShare(selected.currentNumerator, selected.currentDenominator); const comparisonPercentage = selected.comparisonNumerator !== undefined && selected.comparisonDenominator !== undefined ? getStatisticShare(selected.comparisonNumerator, selected.comparisonDenominator) : undefined; const exportValue = async (format: "png" | "pdf" | "word") => { setError(""); setExporting(format); try { if (format === "png") { const target = document.getElementById(targetId); if (!target) throw new Error("No export target"); await downloadStatisticsChartPng(target, `custom statistic ${selected.title}`); } else await downloadCustomStatisticDocument(selected, currentLabel, comparisonPercentage === undefined ? undefined : comparisonLabel, format); } catch { setError("The custom statistic could not be exported. Please try again."); } finally { setExporting(null); } }; return <section className="rounded-2xl border border-[#b8dcd5] bg-white p-5 shadow-sm"><div className="flex flex-col gap-2 sm:flex-row sm:items-start sm:justify-between"><div><div className="flex items-center gap-2 text-xs font-bold tracking-[0.12em] text-[#397a72]"><Calculator className="h-4 w-4" />CUSTOM RESEARCH STATISTIC</div><h2 className="mt-2 font-display text-2xl text-[#1d3c46]">Build an aggregate proportion</h2><p className="mt-1 max-w-3xl text-sm leading-6 text-slate-500">Choose a pre-approved numerator and denominator definition. Free text and record-level fields are intentionally not available.</p></div><ChartHelp label="custom research statistic">The numerator and denominator are fixed aggregate definitions. The selected statistic follows the page filters and dates.</ChartHelp></div><div className="mt-4 grid gap-3 md:grid-cols-2"><div><label htmlFor="custom-statistic-family" className="mb-1.5 block text-xs font-medium text-[#45616a]">Research question family</label><Select value={family} onValueChange={value => { setFamily(value as CustomStatisticFamily); setSelectedKey(""); }}><SelectTrigger id="custom-statistic-family"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="cohort">Cohort share of all matching records</SelectItem><SelectItem value="completion">Completion status share</SelectItem><SelectItem value="enrollment">Enrollment status share</SelectItem><SelectItem value="data_quality">Data-quality status share</SelectItem><SelectItem value="clinical_indicator">Cohort clinical indicator</SelectItem></SelectContent></Select></div><div><label htmlFor="custom-statistic-option" className="mb-1.5 block text-xs font-medium text-[#45616a]">Aggregate numerator / denominator</label><Select value={selected.key} onValueChange={setSelectedKey}><SelectTrigger id="custom-statistic-option"><SelectValue /></SelectTrigger><SelectContent>{familyOptions.map(option => <SelectItem key={option.key} value={option.key}>{option.title}</SelectItem>)}</SelectContent></Select></div></div><div id={targetId} className="mt-4 rounded-xl bg-[#f6fbf9] p-4"><p className="text-xs font-semibold tracking-wide text-[#397a72]">SELECTED AGGREGATE QUESTION</p><h3 className="mt-1 text-lg font-semibold text-[#24434b]">{selected.title}</h3><p className="mt-1 text-sm text-[#587579]">{selected.numeratorLabel} / {selected.denominatorLabel}</p><div className="mt-3 grid gap-3 sm:grid-cols-2"><div><p className="text-3xl font-semibold text-[#1d3c46]">{currentPercentage}%</p><p className="mt-1 text-xs text-[#587579]">{selected.currentNumerator} of {selected.currentDenominator} · {currentLabel}</p></div>{comparisonPercentage !== undefined ? <div><p className="text-3xl font-semibold text-[#685f98]">{comparisonPercentage}%</p><p className="mt-1 text-xs text-[#587579]">{selected.comparisonNumerator} of {selected.comparisonDenominator} · {comparisonLabel}</p><div className="mt-2"><ComparisonSignal current={currentPercentage} comparison={comparisonPercentage} percentagePoints /></div></div> : null}</div><ChartContainer config={chartConfig} className="mt-3 h-[180px] w-full"><BarChart accessibilityLayer data={[{ label: "Selected proportion", current: currentPercentage, comparison: comparisonPercentage ?? 0 }]} margin={{ left: -18, right: 8, top: 8 }}><CartesianGrid vertical={false} stroke="#e7efec" /><XAxis dataKey="label" hide /><YAxis domain={[0, 100]} tickFormatter={value => `${value}%`} tickLine={false} axisLine={false} width={40} /><ChartTooltip cursor={{ fill: "#edf7f4" }} content={<ChartTooltipContent formatter={(value, name) => `${value}% ${name === "comparison" ? "in comparison period" : "in current period"}`} />} />{comparisonPercentage !== undefined ? <Legend formatter={value => value === "current" ? "Current period" : "Comparison period"} /> : null}<Bar name="current" dataKey="current" fill="var(--color-current)" radius={[5, 5, 0, 0]} />{comparisonPercentage !== undefined ? <Bar name="comparison" dataKey="comparison" fill="var(--color-comparison)" radius={[5, 5, 0, 0]} /> : null}</BarChart></ChartContainer><div className="mt-3 space-y-1 text-sm leading-6 text-[#45616a]">{buildCustomStatisticSummary(selected, currentLabel, comparisonPercentage === undefined ? undefined : comparisonLabel).map(line => <p key={line}>{line}</p>)}</div></div><div className="mt-4 flex flex-wrap items-center gap-2"><Button type="button" variant="outline" onClick={() => downloadAggregateStatisticsCsv(createCustomStatisticCsv(selected, currentLabel, comparisonPercentage === undefined ? undefined : comparisonLabel))}><Download className="mr-2 h-4 w-4" />Export CSV</Button><Button type="button" variant="outline" disabled={exporting !== null} onClick={() => exportValue("png")}><ImageDown className="mr-2 h-4 w-4" />{exporting === "png" ? "Preparing PNG…" : "Export PNG"}</Button><Button type="button" variant="outline" disabled={exporting !== null} onClick={() => exportValue("pdf")}><FileDown className="mr-2 h-4 w-4" />{exporting === "pdf" ? "Preparing PDF…" : "Export PDF"}</Button><Button type="button" variant="outline" disabled={exporting !== null} onClick={() => exportValue("word")}><FileText className="mr-2 h-4 w-4" />{exporting === "word" ? "Preparing Word…" : "Export Word"}</Button>{error ? <p role="status" className="text-xs text-rose-700">{error}</p> : null}</div></section>; }

export default function RegistryStatistics() {
  const initial = React.useRef(readStatisticsViewPreference()).current;
  const [cohort, setCohort] = React.useState<StatisticsCohort>(initial.cohort);
  const [completeness, setCompleteness] = React.useState<CompletionStatus>(initial.completeness);
  const [enrollment, setEnrollment] = React.useState<EnrollmentStatus>(initial.enrollment);
  const [startDate, setStartDate] = React.useState(initial.startDate);
  const [endDate, setEndDate] = React.useState(initial.endDate);
  const [comparisonStartDate, setComparisonStartDate] = React.useState(initial.comparisonStartDate);
  const [comparisonEndDate, setComparisonEndDate] = React.useState(initial.comparisonEndDate);
  const invalid = Boolean(startDate && endDate && startDate > endDate) || Boolean(comparisonStartDate) !== Boolean(comparisonEndDate) || Boolean(comparisonStartDate && comparisonEndDate && comparisonStartDate > comparisonEndDate) || Boolean((comparisonStartDate || comparisonEndDate) && (!startDate || !endDate)) || Boolean(startDate && endDate && comparisonStartDate && comparisonEndDate && startDate === comparisonStartDate && endDate === comparisonEndDate);
  const errorText = startDate && endDate && startDate > endDate ? "The current period end date must be on or after its start date." : Boolean(comparisonStartDate) !== Boolean(comparisonEndDate) ? "Enter both comparison dates." : (comparisonStartDate || comparisonEndDate) && (!startDate || !endDate) ? "Choose both current-period dates before comparing periods." : comparisonStartDate && comparisonEndDate && comparisonStartDate > comparisonEndDate ? "The comparison end date must be on or after its start date." : "Choose a different comparison period.";
  const currentLabel = getStatisticsDateRangeLabel(startDate || undefined, endDate || undefined);
  const comparisonLabel = getStatisticsDateRangeLabel(comparisonStartDate || undefined, comparisonEndDate || undefined);
  const preference = { cohort, completeness, enrollment, startDate, endDate, comparisonStartDate, comparisonEndDate };
  const input = React.useMemo(() => ({ cohort: cohort === "all" ? undefined : cohort, completenessStatus: completeness === "all" ? undefined : completeness, enrollmentStatus: enrollment === "all" ? undefined : enrollment, startDate: startDate || undefined, endDate: endDate || undefined, comparisonStartDate: comparisonStartDate || undefined, comparisonEndDate: comparisonEndDate || undefined }), [cohort, completeness, enrollment, startDate, endDate, comparisonStartDate, comparisonEndDate]);
  const { data: rawData, isLoading, error } = trpc.registry.statistics.useQuery(input, { enabled: !invalid });
  const data = rawData as AggregateStatistics | undefined;
  const comparison = data?.comparison;
  const comparisonById = new Map((comparison?.cohortIndicators ?? []).map(item => [item.id, item]));
  const visibleIndicators = (data?.cohortIndicators ?? []).filter(item => item.denominator > 0 || (comparisonById.get(item.id)?.denominator ?? 0) > 0);
  const total = data?.totalRecords ?? 0;
  const completed = data?.byCompleteness.find(row => row.status === "complete")?.total ?? 0;
  const clear = () => { setCohort("all"); setCompleteness("all"); setEnrollment("all"); setStartDate(""); setEndDate(""); setComparisonStartDate(""); setComparisonEndDate(""); };
  const noFilters = JSON.stringify(preference) === JSON.stringify(defaultPreference);
  return <div className="mx-auto max-w-7xl space-y-6 fade-rise">
    <section className="rounded-[1.5rem] border border-[#dce9e5] bg-white p-6 shadow-sm"><div className="flex flex-col gap-4"><div className="flex flex-col gap-4 xl:flex-row xl:items-end xl:justify-between"><div><div className="flex items-center gap-2 text-xs font-bold tracking-[0.14em] text-[#397a72]"><BarChart3 className="h-4 w-4" />AGGREGATE RESEARCH ANALYTICS</div><h1 className="mt-2 font-display text-3xl text-[#1d3c46]">Registry statistics</h1><p className="mt-2 max-w-3xl text-sm leading-6 text-slate-500">Explore aggregate research operations without displaying Research IDs, patient details, clinical narratives, user identities, or free text.</p></div><Button variant="outline" className="border-[#b8dcd5] text-[#22636a]" disabled={!data || isLoading || invalid} onClick={() => data && downloadAggregateStatisticsCsv(createAggregateStatisticsCsv(data, currentLabel, comparison, comparison ? comparisonLabel : undefined))}><Download className="mr-2 h-4 w-4" />{comparison ? "Download comparison CSV" : "Download aggregate CSV"}</Button></div><ReportActions data={data} comparison={comparison} preference={preference} currentLabel={currentLabel} comparisonLabel={comparisonLabel} /></div></section>
    <section className="rounded-2xl border border-[#dce9e5] bg-[#f6fbf9] p-4"><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4"><div><label htmlFor="statistics-cohort" className="mb-1.5 block text-xs font-medium text-[#45616a]">Cohort</label><Select value={cohort} onValueChange={value => setCohort(value as StatisticsCohort)}><SelectTrigger id="statistics-cohort"><SelectValue /></SelectTrigger><SelectContent>{cohorts.map(option => <SelectItem key={option.value} value={option.value}>{option.label}</SelectItem>)}</SelectContent></Select></div><div><label htmlFor="statistics-completeness" className="mb-1.5 block text-xs font-medium text-[#45616a]">Completion status</label><Select value={completeness} onValueChange={value => setCompleteness(value as CompletionStatus)}><SelectTrigger id="statistics-completeness"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">All completion states</SelectItem><SelectItem value="complete">Complete</SelectItem><SelectItem value="incomplete">Incomplete</SelectItem><SelectItem value="needs_review">Needs review</SelectItem></SelectContent></Select></div><div><label htmlFor="statistics-enrollment" className="mb-1.5 block text-xs font-medium text-[#45616a]">Enrollment status</label><Select value={enrollment} onValueChange={value => setEnrollment(value as EnrollmentStatus)}><SelectTrigger id="statistics-enrollment"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">All enrollment states</SelectItem><SelectItem value="screened">Screened</SelectItem><SelectItem value="enrolled">Enrolled</SelectItem><SelectItem value="completed">Completed</SelectItem><SelectItem value="withdrawn">Withdrawn</SelectItem><SelectItem value="ineligible">Ineligible</SelectItem></SelectContent></Select></div><div className="flex items-end"><Button variant="outline" className="w-full" onClick={clear} disabled={noFilters}><FilterX className="mr-2 h-4 w-4" />Clear filters</Button></div></div><div className="mt-4 grid gap-3 border-t border-[#dce9e5] pt-4 md:grid-cols-2 xl:grid-cols-4"><div><label htmlFor="statistics-start-date" className="mb-1.5 block text-xs font-medium text-[#45616a]">Current period from (UTC)</label><Input id="statistics-start-date" type="date" value={startDate} max={endDate || undefined} onChange={event => setStartDate(event.target.value)} aria-invalid={invalid} /></div><div><label htmlFor="statistics-end-date" className="mb-1.5 block text-xs font-medium text-[#45616a]">Current period to (UTC)</label><Input id="statistics-end-date" type="date" value={endDate} min={startDate || undefined} onChange={event => setEndDate(event.target.value)} aria-invalid={invalid} /></div><div><label htmlFor="statistics-comparison-start-date" className="mb-1.5 block text-xs font-medium text-[#45616a]">Compare with period from (UTC)</label><Input id="statistics-comparison-start-date" type="date" value={comparisonStartDate} max={comparisonEndDate || undefined} onChange={event => setComparisonStartDate(event.target.value)} aria-invalid={invalid} /></div><div><label htmlFor="statistics-comparison-end-date" className="mb-1.5 block text-xs font-medium text-[#45616a]">Compare with period to (UTC)</label><Input id="statistics-comparison-end-date" type="date" value={comparisonEndDate} min={comparisonStartDate || undefined} onChange={event => setComparisonEndDate(event.target.value)} aria-invalid={invalid} /></div></div>{invalid ? <p role="alert" className="mt-3 text-xs font-medium text-rose-700">{errorText}</p> : <p className="mt-3 flex items-center gap-1.5 text-xs leading-5 text-[#587579]"><CalendarRange className="h-3.5 w-3.5 shrink-0 text-[#277166]" />Use both dates for the current period, then optionally select both comparison dates. Save view stores only these settings in this browser.</p>}<p className="mt-1 flex items-center gap-1.5 text-xs leading-5 text-[#587579]"><ShieldCheck className="h-3.5 w-3.5 shrink-0 text-[#277166]" />Filters, reports, and charts use aggregate counts only. Individual research records are never returned or exported by this page.</p></section>
    {invalid ? <Card className="border-rose-200 bg-rose-50"><CardContent className="p-5 text-sm text-rose-800">Correct the date ranges to update the aggregate statistics.</CardContent></Card> : error ? <Card className="border-rose-200 bg-rose-50"><CardContent className="p-5 text-sm text-rose-800">Aggregate statistics are unavailable: {error.message}</CardContent></Card> : isLoading ? <section className="grid gap-4 md:grid-cols-3">{[1, 2, 3].map(item => <Skeleton key={item} className="h-36 rounded-xl" />)}</section> : data ? <><CustomStatisticBuilder data={data} comparison={comparison} currentLabel={currentLabel} comparisonLabel={comparisonLabel} /><section className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><Metric label="Matching records" value={total} description="Aggregate count for the current period." comparisonValue={comparison?.totalRecords} /><Metric label="Complete records" value={completed} description={`${getStatisticShare(completed, total)}% of the current aggregate view.`} comparisonValue={comparison?.byCompleteness.find(row => row.status === "complete")?.total} /><Metric label="Protocol checklists complete" value={data.investigationCoverage.protocolChecklistComplete} description="Records with a completed or not-indicated checklist." comparisonValue={comparison?.investigationCoverage.protocolChecklistComplete} /><Metric label="Laboratory recorded" value={data.investigationCoverage.laboratoryRecorded} description="Aggregate coverage, not individual results." comparisonValue={comparison?.investigationCoverage.laboratoryRecorded} /></section>{comparison ? <ComparisonSummary data={data} comparison={comparison} currentLabel={currentLabel} comparisonLabel={comparisonLabel} /> : null}{visibleIndicators.length ? <section className="space-y-3"><div><h2 className="font-display text-2xl text-[#1d3c46]">Cohort indicators</h2><p className="mt-1 text-sm text-slate-500">Research-oriented rates derived only from controlled cohort fields.</p></div><div className="grid gap-5 xl:grid-cols-2">{visibleIndicators.map(item => <CohortIndicatorCard key={item.id} indicator={item} comparison={comparisonById.get(item.id)} currentDateRangeLabel={currentLabel} comparisonDateRangeLabel={comparison ? comparisonLabel : undefined} />)}</div></section> : null}{total === 0 && (comparison?.totalRecords ?? 0) === 0 ? <Card className="border-[#e1e9e5]"><CardContent className="p-8 text-center"><Microscope className="mx-auto h-8 w-8 text-[#5e928a]" /><h2 className="mt-3 font-display text-xl text-[#25424a]">No matching aggregate data</h2><p className="mt-2 text-sm text-slate-500">Adjust or clear the filters to review available registry statistics.</p></CardContent></Card> : comparison ? <section className="grid gap-5 xl:grid-cols-2"><AggregateComparisonBarChart title="Cohort distribution" currentRows={data.byCohort} comparisonRows={comparison.byCohort} currentDateRangeLabel={currentLabel} comparisonDateRangeLabel={comparisonLabel} /><AggregateComparisonBarChart title="Completion status" currentRows={data.byCompleteness} comparisonRows={comparison.byCompleteness} currentDateRangeLabel={currentLabel} comparisonDateRangeLabel={comparisonLabel} /><AggregateComparisonBarChart title="Enrollment status" currentRows={data.byEnrollment} comparisonRows={comparison.byEnrollment} currentDateRangeLabel={currentLabel} comparisonDateRangeLabel={comparisonLabel} /><AggregateComparisonBarChart title="Data quality state" currentRows={data.byDataQuality} comparisonRows={comparison.byDataQuality} currentDateRangeLabel={currentLabel} comparisonDateRangeLabel={comparisonLabel} /></section> : <section className="grid gap-5 xl:grid-cols-2"><AggregateDonutChart title="Cohort distribution" description="Select a cohort to update the aggregate view." data={toAggregateChartData(data.byCohort, "cohort")} total={total} selectedKey={cohort} onSelect={key => setCohort(key as StatisticsCohort)} dateRangeLabel={currentLabel} /><AggregateDonutChart title="Completion status" description="Select a completion state to update the aggregate view." data={toAggregateChartData(data.byCompleteness, "completion")} total={total} selectedKey={completeness} onSelect={key => setCompleteness(key as CompletionStatus)} dateRangeLabel={currentLabel} /><AggregateBarChart title="Enrollment status" data={toAggregateChartData(data.byEnrollment)} total={total} dateRangeLabel={currentLabel} /><AggregateBarChart title="Data quality state" data={toAggregateChartData(data.byDataQuality)} total={total} dateRangeLabel={currentLabel} /></section>}</> : null}
  </div>;
}
